using System.Data.Common;
using Microsoft.Data.SqlClient;
using Npgsql;
using MySqlConnector;
using FirebirdSql.Data.FirebirdClient;

namespace SnapData.IntegrationTests;

public sealed class DefaultInsertProviderTests
{
    [PostgresFact]
    public Task PostgreSql_defaults_and_identity() => RunAsync(NpgsqlFactory.Instance,
        "SNAPDATA_POSTGRES_CONNECTION", PostgresQueryCompiler.Instance, "BIGINT GENERATED BY DEFAULT AS IDENTITY");

    [SqlServerFact]
    public Task SqlServer_defaults_and_identity() => RunAsync(SqlClientFactory.Instance,
        "SNAPDATA_SQLSERVER_CONNECTION", SqlServerQueryCompiler.Instance, "BIGINT IDENTITY");

    [MySqlFact]
    public Task MySql_defaults_and_identity() => RunAsync(MySqlConnectorFactory.Instance,
        "SNAPDATA_MYSQL_CONNECTION", MySqlQueryCompiler.Instance, "BIGINT AUTO_INCREMENT");

    [FirebirdFact]
    public Task Firebird_defaults_and_identity() => RunAsync(FirebirdClientFactory.Instance,
        "SNAPDATA_FIREBIRD_CONNECTION", FirebirdQueryCompiler.Instance, "BIGINT GENERATED BY DEFAULT AS IDENTITY");

    private static async Task RunAsync(DbProviderFactory factory, string variable, IQueryCompiler compiler, string identity)
    {
        var table = "DEFAULT_" + Guid.NewGuid().ToString("N")[..20].ToUpperInvariant();
        var mapping = new EntityMappingProvider(new MappingOptions { TableName = _ => table });
        var database = new SnapDatabase(factory, Environment.GetEnvironmentVariable(variable)!, compiler, mapping);
        await using var session = await database.OpenSessionAsync();
        var quotedTable = compiler == MySqlQueryCompiler.Instance ? $"`{table}`"
            : compiler == SqlServerQueryCompiler.Instance ? $"[{table}]" : $"\"{table}\"";
        var quotedId = compiler == FirebirdQueryCompiler.Instance ? "\"ID\"" : "id";
        var quotedLabel = compiler == FirebirdQueryCompiler.Instance ? "\"LABEL\"" : "label";
        await session.ExecuteAsync($"CREATE TABLE {quotedTable} ({quotedId} {identity} PRIMARY KEY, {quotedLabel} VARCHAR(40) DEFAULT 'server')");
        try
        {
            var item = new IdentityOnly();
            Assert.Equal(1, await session.InsertAsync(item));
            Assert.True(item.Id > 0);
            Assert.Equal("server", await session.ScalarAsync<string>($"SELECT {quotedLabel} FROM {quotedTable} WHERE {quotedId} = @id", new { id = item.Id }));
            if (compiler.Capabilities.InsertReturning)
            {
                var returned = await session.InsertInto<IdentityOnly>().DefaultValues().Returning<long>(x => x.Id).SingleAsync();
                Assert.True(returned > item.Id);
            }
            else
            {
                Assert.Equal(1, await session.InsertInto<IdentityOnly>().DefaultValues().ExecuteAsync());
                var before = await session.From<IdentityOnly>().CountAsync();
                await Assert.ThrowsAsync<NotSupportedException>(() => session.InsertAsync(new GeneratedPair()));
                Assert.Equal(before, await session.From<IdentityOnly>().CountAsync());
            }
            await session.InsertInto<IdentityOnly>().Values(new IdentityOnly()).ExecuteAsync();
            await session.ExecuteAsync(Sql.InsertInto(table).Value("label", null));
            Assert.Equal(4, await session.From<IdentityOnly>().CountAsync());
            Assert.Equal(1, await session.ScalarAsync<int>($"SELECT COUNT(*) FROM {quotedTable} WHERE {quotedLabel} IS NULL"));
            if (compiler != MySqlQueryCompiler.Instance)
            {
                var generated = new GeneratedPair();
                await session.InsertAsync(generated);
                Assert.True(generated.Id > 0);
                Assert.Equal("server", generated.Label);
            }
        }
        finally { await session.ExecuteAsync($"DROP TABLE {quotedTable}"); }
    }

    private sealed class IdentityOnly
    {
        [Key, Column("id"), DatabaseGenerated(DatabaseGeneratedOption.Identity)] public long Id { get; set; }
    }
    private sealed class GeneratedPair
    {
        [Key, Column("id"), DatabaseGenerated(DatabaseGeneratedOption.Identity)] public long Id { get; set; }
        [Column("label"), DatabaseGenerated(DatabaseGeneratedOption.Computed)] public string? Label { get; set; }
    }
}
